using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------
var notebook = new ResearchNotebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for the given query and returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("Short label for the note")] string title,
         [Description("The content to save")] string content) =>
        {
            notebook.Add(title, content);
            return $"Saved note \"{title}\".";
        },
        "save_note",
        "Saves a research note for later reference when writing the summary."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieves all previously saved research notes."),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic function invocation
// ---------------------------------------------------------------------------
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Agent system prompt
// ---------------------------------------------------------------------------
const string SystemPrompt = """
    You are a research agent. Your job is to thoroughly research a topic the user
    provides and produce a well-structured summary.

    Follow this workflow:
    1. Break the topic into 2-3 key sub-questions.
    2. For each sub-question, call `web_search` with a targeted query.
    3. After each search, call `save_note` to record the most important findings.
    4. When you have gathered enough information, call `get_notes` to review
       everything you collected.
    5. Finally, write a comprehensive summary with sections, citing the sources
       where possible.

    Be thorough but concise. Focus on factual, well-sourced information.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       🔍  AI Research Agent  🔍         ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic: ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching… (the agent will search the web and take notes)\n");
    Console.ResetColor();

    notebook.Clear();

    List<ChatMessage> messages =
    [
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Please research the following topic: {topic}"),
    ];

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("── Research Summary ─────────────────────────────────");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine("─────────────────────────────────────────────────────\n");
}

Console.WriteLine("Goodbye!");

