/// <summary>Web search tool that uses the Bing Search API when available,
/// falling back to a DuckDuckGo HTML scrape.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(string query)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔎  Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Try Bing Search API first if a key is configured
            var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
            if (!string.IsNullOrEmpty(bingKey))
                return await SearchBingAsync(query, bingKey);

            // Fallback: DuckDuckGo instant-answer API (no key needed)
            return await SearchDuckDuckGoAsync(query);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static async Task<string> SearchBingAsync(string query, string apiKey)
    {
        var url = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

        using var response = await Http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var sb = new StringBuilder();

        if (doc.RootElement.TryGetProperty("webPages", out var pages) &&
            pages.TryGetProperty("value", out var results))
        {
            foreach (var r in results.EnumerateArray())
            {
                var name = r.GetProperty("name").GetString();
                var snippet = r.GetProperty("snippet").GetString();
                var resultUrl = r.GetProperty("url").GetString();
                sb.AppendLine($"- **{name}** ({resultUrl})\n  {snippet}\n");
            }
        }

        return sb.Length > 0 ? sb.ToString() : "No results found.";
    }

    private static async Task<string> SearchDuckDuckGoAsync(string query)
    {
        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        var response = await Http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var html = await response.Content.ReadAsStringAsync();
        var sb = new StringBuilder();
        int count = 0;

        // Parse result snippets from the HTML response
        int pos = 0;
        while (count < 5 && (pos = html.IndexOf("class=\"result__snippet\"", pos, StringComparison.Ordinal)) >= 0)
        {
            int start = html.IndexOf('>', pos) + 1;
            int end = html.IndexOf("</a>", start, StringComparison.Ordinal);
            if (start > 0 && end > start)
            {
                var snippet = StripHtml(html[start..end]).Trim();
                if (snippet.Length > 0)
                {
                    sb.AppendLine($"- {snippet}");
                    count++;
                }
            }
            pos = end > 0 ? end : pos + 1;
        }

        return sb.Length > 0 ? sb.ToString() : "No results found (DuckDuckGo fallback).";
    }

    private static string StripHtml(string html) =>
        System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", "")
            .Replace("&amp;", "&").Replace("&lt;", "<")
            .Replace("&gt;", ">").Replace("&quot;", "\"")
            .Replace("&#x27;", "'");
}

